import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.ChTAMbUy.js";const g=JSON.parse('{"title":"AgentOps","description":"","frontmatter":{},"headers":[],"relativePath":"development/agentops/index.md","filePath":"versions/development/agentops/index.md","lastUpdated":1787837970000}'),r={name:"development/agentops/index.md"};function s(l,e,i,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="agentops" tabindex="-1">AgentOps <a class="header-anchor" href="#agentops" aria-label="Permalink to &quot;AgentOps&quot;">​</a></h1><p>AgentOps in prokube covers the operational path for building, connecting, exposing, and observing AI agents on controlled workspace infrastructure.</p><p>Use <a href="./../labs/">Labs</a> for interactive development and debugging. Use AgentOps when agent workflows need managed models, governed tool access, sandboxed execution, memory, external API access, or agent-to-agent integration.</p><h2 id="main-workflows" tabindex="-1">Main Workflows <a class="header-anchor" href="#main-workflows" aria-label="Permalink to &quot;Main Workflows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>Use</th></tr></thead><tbody><tr><td><a href="./agents.html">Agents</a></td><td>Create kagent agents, attach model configurations and tools, test conversations, and expose agents over A2A.</td></tr><tr><td><a href="./llm_serving.html">LLM Serving</a></td><td>Deploy self-hosted OpenAI-compatible models for agents and other LLM clients, including tool-calling support where available.</td></tr><tr><td><a href="./mcp_servers.html">MCP Servers</a></td><td>Run governed MCP tool servers in a workspace and expose their tools to agents, OpenCode, and external MCP clients.</td></tr><tr><td><a href="./sandboxes.html">Agent Sandboxes</a></td><td>Give agents isolated execution environments for code, shell commands, files, package installation, and stateful task execution.</td></tr><tr><td><a href="./memory_stores.html">Memory Stores</a></td><td>Provide workspace-scoped state and retrieval capabilities for agent workflows.</td></tr><tr><td><a href="./agent_gateway.html">Agent Gateway</a></td><td>Expose models, MCP servers, agents, sandboxes, and serving endpoints to external clients through scoped API keys.</td></tr></tbody></table><h2 id="typical-flow" tabindex="-1">Typical Flow <a class="header-anchor" href="#typical-flow" aria-label="Permalink to &quot;Typical Flow&quot;">​</a></h2><ol><li>Choose a model path: use an administrator-granted external model, create a workspace Model Configuration, or deploy an in-cluster model with <a href="./llm_serving.html">LLM Serving</a>.</li><li>Prepare any tools the agent needs: deploy <a href="./mcp_servers.html">MCP Servers</a>, connect another agent, or use <a href="./sandboxes.html">Agent Sandboxes</a> for isolated code execution, file operations, package installation, and long-running task state.</li><li>Create an <a href="./agents.html">Agent</a>, attach the Model Configuration, select the MCP or agent tools it may call, and test it in the built-in chat.</li><li>Expose programmatic access through <a href="./agent_gateway.html">Agent Gateway</a> only when external clients, SDKs, CI jobs, or other integrations need to call the service without a browser session.</li><li>Use logs, events, metrics, traces, and API-key usage data to debug behavior and review operational impact.</li></ol><h2 id="access-model" tabindex="-1">Access Model <a class="header-anchor" href="#access-model" aria-label="Permalink to &quot;Access Model&quot;">​</a></h2><p>AgentOps separates browser-based UI work, internal workspace traffic, and external API traffic.</p><table tabindex="0"><thead><tr><th>Access path</th><th>Typical caller</th><th>Authentication</th></tr></thead><tbody><tr><td>UI</td><td>A user working in pkui</td><td>Browser session and workspace permissions</td></tr><tr><td>Internal workspace traffic</td><td>Agents, MCP servers, models, sandboxes, and other workloads in the same workspace</td><td>Kubernetes and mesh identity</td></tr><tr><td>External API traffic</td><td>SDKs, automation, CI jobs, external MCP clients, and A2A callers</td><td>Agent Gateway API key scoped to the target service</td></tr></tbody></table><p>You usually need API keys only for external clients. In-workspace agents and tools normally use the platform&#39;s internal identity and routing model.</p><h2 id="foundation" tabindex="-1">Foundation <a class="header-anchor" href="#foundation" aria-label="Permalink to &quot;Foundation&quot;">​</a></h2><p>AgentOps workloads run on the shared prokube foundation: workspaces, Kubernetes namespaces, RBAC, secrets, storage, observability, and API-key management.</p><p>Start with these cross-cutting pages when you need platform behavior rather than feature-specific usage:</p><ul><li><a href="./../platform/workspaces.html">Workspaces</a></li><li><a href="./../platform/kubernetes.html">Kubernetes Resources</a></li><li><a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a></li><li><a href="./../platform/observability.html">Observability</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li></ul>',15)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
